TEST(SchemaApi, ProfileScannerRoundTrips) {
    TempDir dir;
    sc::profile_scanner::Attributes a;
    a.frame_id = std::string("v0");
    a.simulated = false;
    a.vendor = std::string("v2");
    a.model = std::string("v3");
    a.serial = std::string("v4");
    a.description = std::string("v5");
    a.points_per_profile = std::uint32_t{2};
    a.wavelength_nm = 7.25;
    a.extra["custom_note"] = std::string("kept");
    auto scan = rs::ScanWriter::create(dir.path());
    auto written = sc::profile_scanner::add(scan, "n0", a);
    sc::profile_scanner::ProfileRow profile_row;
    profile_row.time_ns = 42;
    {
        rs::Array arr(rs::DType::Float32, {2, 3});
        auto* p = static_cast<float*>(arr.data());
        for (int k = 0; k < 6; ++k) p[k] = static_cast<float>((k + 0) % 2);
        profile_row.points = std::move(arr);
    }
    {
        rs::Array arr(rs::DType::UInt16, {2});
        auto* p = static_cast<std::uint16_t*>(arr.data());
        for (int k = 0; k < 2; ++k) p[k] = static_cast<std::uint16_t>((k + 1) % 2);
        profile_row.intensity = std::move(arr);
    }
    auto profile_w = written.segmented_series("profile", {{"points_per_profile", 2}});
    sc::profile_scanner::append(profile_w, profile_row);
    sc::profile_scanner::ProfileColumns profile_cols;
    for (int k = 0; k < 2; ++k) {
        profile_cols.time_ns.push_back(43 + k);
    }
    profile_cols.points = rbscan_test::stack(profile_row.points, 2);
    profile_cols.intensity = rbscan_test::stack((*profile_row.intensity), 2);
    sc::profile_scanner::append(profile_w, profile_cols);
    scan.finalize();  // closes the master; the reader opens it below
    const auto reader = rs::ScanReader::open(dir.path());
    const auto node = reader.node("sensors/n0");
    const auto b = sc::profile_scanner::read(node);
    EXPECT_EQ(a.to_attributes(), b.to_attributes());
    EXPECT_EQ(std::get<std::string>(b.extra.at("custom_note")), "kept");
    {
        const auto rows = sc::profile_scanner::read_profile_rows(node);
        ASSERT_EQ(rows.size(), 3u);
        EXPECT_EQ(rows[2].time_ns, 44);
        for (const auto& r : rows) {
            EXPECT_TRUE(rbscan_test::same(r.points, profile_row.points));
            ASSERT_TRUE(r.intensity.has_value());
            EXPECT_TRUE(rbscan_test::same((*r.intensity), (*profile_row.intensity)));
        }
    }
}

