    sc::xray_detector::StateRow state_row;
    state_row.time_ns = 42;
    state_row.binning = std::uint8_t{2};
    state_row.image_width = std::uint32_t{3};
    state_row.image_height = std::uint32_t{4};
    state_row.integration_time_ms = 3.25;
    state_row.averages = std::uint32_t{6};
    state_row.gain = 5.25;
    auto state_w = written.series("state", {});
    sc::xray_detector::append(state_w, state_row);
    sc::xray_detector::StateColumns state_cols;
    for (int k = 0; k < 2; ++k) {
        state_cols.time_ns.push_back(43 + k);
        state_cols.binning.push_back(state_row.binning);
        state_cols.image_width.push_back(state_row.image_width);
        state_cols.image_height.push_back(state_row.image_height);
        state_cols.integration_time_ms.push_back(state_row.integration_time_ms);
        state_cols.averages.push_back(state_row.averages);
        state_cols.gain.push_back(state_row.gain);
    }
