    sc::xray_detector::append(calibration_w, calibration_row);
    sc::xray_detector::CalibrationColumns calibration_cols;
    for (int k = 0; k < 2; ++k) {
        calibration_cols.time_ns.push_back(43 + k);
    }
    calibration_cols.dark = rbscan_test::stack((*calibration_row.dark), 2);
    calibration_cols.flat = rbscan_test::stack((*calibration_row.flat), 2);
    calibration_cols.bad_pixels = rbscan_test::stack((*calibration_row.bad_pixels), 2);
    sc::xray_detector::append(calibration_w, calibration_cols);
    scan.finalize();  // closes the master; the reader opens it below
